SELECT percent_rank() OVER (ORDER BY AVG(labevents.value)) AS percentile_rank FROM labevents JOIN icustays ON labevents.subject_id = icustays.subject_id WHERE icustays.subject_id = 43 AND icustays.stay_id IN (SELECT stay_id FROM icustays WHERE subject_id IN (SELECT subject_id FROM patients WHERE gender = 'F' AND age BETWEEN 38 AND 48)) AND labevents.itemid = 857075 AND labevents.charttime BETWEEN icustays.intime AND icustays.intime + interval '48 hours' GROUP BY icustays.stay_id HAVING AVG(labevents.value) > 130;